import {attachCanvas,draw,resetCamera,getCamera,setCamera} from './renderer.js';
import {installPanelLayouts,saveView,readView,replacePanelContent} from './layout.js';
const $=id=>document.getElementById(id),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>new Intl.NumberFormat('it-IT',{style:'currency',currency:'EUR',maximumFractionDigits:0}).format(n||0);
const date=n=>new Intl.DateTimeFormat('it-IT',{timeZone:'Europe/Rome',day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'}).format(n);
const days=['Lun','Mar','Mer','Gio','Ven','Sab','Dom'],roles={driver:'Pilota',motor:'Motorista',aero:'Ingegnere aerodinamico',mechanic:'Capo meccanico',engine:'Power unit'},compounds={soft:'Soft',medium:'Medium',hard:'Hard',inter:'Intermedie',wet:'Wet'};
let token='',data=null,tab='Paddock',marketRole='driver',follow=null,followCamera=false,received=0,polling=false,busy=false,opened=false,identityDirty=false;
const lastView=readView();if(['Telemetria','Strategia'].includes(lastView.tab))lastView.tab='Box';if(['Paddock','Scuderia','Mercato','Box','Campionato','Evento','Libere','Qualifiche','Gara'].includes(lastView.tab))tab=lastView.tab;follow=typeof lastView.follow==='string'?lastView.follow:null;followCamera=lastView.followCamera===true;setCamera(lastView.camera);let disposePanels=()=>{};
function persistView(){saveView({tab,follow,followCamera,camera:getCamera()})}
const started=performance.now();
function toast(message){$('toast').textContent=message;$('toast').style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('toast').style.display='none',4500)}
function salary(t){return [...t.drivers,...Object.values(t.crew)].reduce((n,d)=>n+(d?.salary||0),0)}
function ready(t){return !!t&&t.drivers.every(Boolean)&&Object.values(t.crew).every(Boolean)&&!!t.engine}
function options(values,selected){return Object.entries(values).map(([v,label])=>`<option value="${v}" ${v===selected?'selected':''}>${esc(label)}</option>`).join('')}
function button(action,label,extra='',cls=''){return `<button class="${cls}" data-action="${action}" ${extra}>${label}</button>`}
async function api(body,{keepalive=false}={}){if(!token)throw Error('Apri Binotto Simulator da Binottoland.');const r=await fetch('/api/simulator/'+(body?'action':'state'),{method:body?'POST':'GET',headers:{Authorization:'Bearer '+token,'Content-Type':'application/json'},...(body?{body:JSON.stringify(body)}:{}),keepalive,signal:AbortSignal.timeout(15000)});const result=await r.json();if(!r.ok){if(r.status===401){token='';parent.postMessage({type:'simulator:ready'},location.origin)}throw Error(result.error||'Connessione interrotta.')}return result}
function accept(next){if(data&&next.revision<data.revision)return false;data=next;loadAutoDrafts();received=performance.now();$('sync').textContent='● ONLINE';$('sync').style.color='var(--teal)';if(tab==='Gara'&&(!follow||!data.race?.cars.some(c=>c.id===follow)))follow=data.race?.cars.find(c=>c.own)?.id||data.race?.cars[0]?.id;updateHeader()}
let chatSending=false,chatPending=null;
const chatKey=()=> 'simulator-chat-draft:'+(data?.viewer?.id||data?.me?.id);
function saveChatDraft(value){if(!data?.viewer?.id&&!data?.me)return;try{localStorage.setItem(chatKey(),value)}catch{}}
function restoreChatDraft(){const input=document.querySelector('[data-form=chat] input');if(input&&(data?.viewer?.id||data?.me))try{input.value=localStorage.getItem(chatKey())||''}catch{}}
const drafts=new Map();let commandTail=Promise.resolve(),pendingCommands=0;
const formKey=f=>f.dataset.form+':'+(f.dataset.form==='session-setup'?f.dataset.mode+':'+f.dataset.event+':':'')+(f.dataset.slot||'');
function rememberDraft(f){if(f.dataset.form==='chat'){saveChatDraft(f.elements.text.value);return}if(!['identity','strategy','proposal','live','session-setup'].includes(f.dataset.form))return;drafts.set(formKey(f),Array.from(f.elements).filter(el=>el.name).map(el=>({name:el.name,value:el.value,checked:el.checked,type:el.type})));if(f.dataset.form==='identity')identityDirty=true;formNotice(f,f.dataset.form==='proposal'?'Bozza conservata; pubblica per condividerla.':'Salvataggio automatico…');queueAutoSave(f);persistAutoDrafts();}
function formNotice(f,message){if(!f?.isConnected)return;let out=f.querySelector('[data-save-status]');if(!out){out=document.createElement('output');out.dataset.saveStatus='';out.setAttribute('role','status');out.style.cssText='display:block;margin-top:10px';f.append(out)}out.textContent=message;}
function restoreDrafts(){for(const f of document.querySelectorAll('[data-form]')){const draft=drafts.get(formKey(f));if(!draft)continue;for(const entry of draft){const el=Array.from(f.elements).find(el=>el.name===entry.name&&(entry.type!=='checkbox'||el.value===entry.value));if(el){el.value=entry.value;if(entry.type==='checkbox')el.checked=entry.checked}}formNotice(f,autoJobs.has(formKey(f))?'Salvataggio automatico in attesa…':'Bozza conservata');if(f.dataset.form==='identity'){const fd=new FormData(f);$('livery').innerHTML=car({count:Number(fd.get('count')),colors:[0,1,2].map(i=>fd.get('color'+i))})}}}
function command(body,{quiet=false,automatic=false}={}){const key=body.action+':'+(body.action==='session-setup'?body.mode+':'+body.event+':':'')+(['strategy','live','session-setup'].includes(body.action)?body.slot:''),submittedDraft=drafts.get(key);const findForm=()=>Array.from(document.querySelectorAll('[data-form]')).find(f=>formKey(f)===key);body=JSON.parse(JSON.stringify(body));pendingCommands++;busy=true;formNotice(findForm(),'Salvataggio in corso…');const job=commandTail.then(async()=>{try{accept(await api(body));if(drafts.get(key)===submittedDraft)drafts.delete(key);identityDirty=drafts.has('identity:');persistAutoDrafts();if(!quiet){render();formNotice(findForm(),drafts.has(key)?'Salvato. Ci sono nuove modifiche da salvare.':'Salvato sul server ✓');toast(body.action==='strategy'?'Piano pilota '+(body.slot+1)+' salvato':'Salvato sul server')}return true}catch(e){formNotice(findForm(),'Non salvato: '+e.message);if(!automatic)toast(e.message);return false}finally{pendingCommands--;busy=pendingCommands>0}});commandTail=job.catch(()=>{});return job;}

const autoJobs=new Map();let autoOwner=null,autoTimer=0,autoRunning=false;
const autoKey=()=> 'simulator-autosave:'+data?.me?.id;
function persistAutoDrafts(){if(!data?.me)return;try{localStorage.setItem(autoKey(),JSON.stringify({drafts:[...drafts],jobs:[...autoJobs]}))}catch{}}
function loadAutoDrafts(){if(!data?.me||autoOwner===data.me.id)return;autoOwner=data.me.id;drafts.clear();autoJobs.clear();try{const saved=JSON.parse(localStorage.getItem(autoKey())||'{}');for(const [k,v] of saved.drafts||[])if(Array.isArray(v))drafts.set(k,v);for(const [k,v] of saved.jobs||[])if(v?.body&&['identity','strategy','live','session-setup'].includes(v.body.action)&&(v.body.action!=='live'||v.race===data.race?.id)&&(v.body.action!=='session-setup'||v.body.event===data.sessions?.event))autoJobs.set(k,v)}catch{}identityDirty=drafts.has('identity:');scheduleAutoSave()}
function scheduleAutoSave(){clearTimeout(autoTimer);autoTimer=setTimeout(flushAutoSaves,400)}
function queueAutoSave(f){const key=formKey(f),type=f.dataset.form;if(!['identity','strategy','live','session-setup'].includes(type))return;if(!f.checkValidity()){autoJobs.delete(key);formNotice(f,'Bozza salvata: completa i valori validi');return}const fd=new FormData(f),slot=Number(f.dataset.slot);let body;if(type==='identity')body={action:type,name:fd.get('name'),count:Number(fd.get('count')),colors:[0,1,2].map(i=>fd.get('color'+i))};else if(type==='session-setup')body={action:type,mode:f.dataset.mode,event:data.sessions.event,slot,setup:getSessionSetup(f)};else body={action:type,slot,strategy:getStrategy(f)};if(type==='live'){const c=data.race?.cars.find(c=>c.own&&c.slot===slot);if(!c)return;}autoJobs.set(key,{body,race:data.race?.id});scheduleAutoSave()}
async function flushAutoSaves(){clearTimeout(autoTimer);if(autoRunning||!token||!data?.me)return;autoRunning=true;const batch=[...autoJobs];try{for(const [key,job] of batch){if(autoJobs.get(key)!==job)continue;if(!drafts.has(key)){autoJobs.delete(key);continue}if((job.body.action==='live'&&job.race!==data.race?.id)||(job.body.action==='session-setup'&&job.body.event!==data.sessions?.event)){autoJobs.delete(key);drafts.delete(key);continue}const ok=await command(job.body,{quiet:true,automatic:true});if(ok&&autoJobs.get(key)===job){autoJobs.delete(key);const f=[...document.querySelectorAll('[data-form]')].find(f=>formKey(f)===key);formNotice(f,'Salvato automaticamente ✓')}persistAutoDrafts()}}finally{autoRunning=false;if([...autoJobs].some(([k,v])=>!batch.some(([bk,bv])=>k===bk&&v===bv)))scheduleAutoSave()}}
window.addEventListener('online',flushAutoSaves);
setInterval(()=>{if(!document.hidden&&autoJobs.size)flushAutoSaves()},10000);

async function poll(){if(polling||busy||!token||document.hidden)return;polling=true;try{const next=await api();const changed=next.revision!==data?.revision;const raceChanged=next.race?.id!==data?.race?.id||next.race?.active!==data?.race?.active;accept(next);if(!opened){const delay=Math.max(0,2000-(performance.now()-started));setTimeout(()=>{$('splash').hidden=true;$('app').hidden=false;opened=true;render();presence()},delay)}else if((raceChanged&&!document.body.classList.contains('panel-dragging')&&!identityDirty)||(changed&&!document.body.classList.contains('panel-dragging')&&!identityDirty&&!['Gara','Libere','Qualifiche'].includes(tab)&&!$('modal').open&&!$('main').contains(document.activeElement)))render();else if(tab==='Gara')updateRace();else if(['Libere','Qualifiche'].includes(tab))updateSessions();else{updateCommunity();updateEventBoard()}}catch(e){$('sync').textContent='● RICONNESSIONE';$('sync').style.color='#ffad85';if(!opened){$('connection').textContent=e.message;$('retry').hidden=false}}finally{polling=false}}
async function presence(){if((busy&&!document.hidden)||!data?.me||!token)return;try{const next=await api({action:'presence',visible:!document.hidden&&opened},{keepalive:document.hidden});accept(next)}catch{}}
setInterval(()=>{if(['Gara','Libere','Qualifiche','Paddock'].includes(tab))poll()},3000);
setInterval(()=>presence(),3000);
setInterval(()=>{if(!['Gara','Libere','Qualifiche','Paddock'].includes(tab))poll()},15000);
document.addEventListener('visibilitychange',()=>{if(document.hidden){persistView();flushAutoSaves()}presence();if(!document.hidden)poll()});
window.addEventListener('message',e=>{if(e.origin!==location.origin||e.source!==parent)return;if(e.data?.type==='simulator:session'&&typeof e.data.token==='string'){token=e.data.token;poll()}if(e.data?.type==='simulator:back'){navigateBack();return}if(e.data?.type==='arcade:insets'){applySimulatorInsets(e.data.insets);fitSimulatorViewport();}});
parent.postMessage({type:'arcade:ready'},location.origin);parent.postMessage({type:'simulator:ready'},location.origin);
$('retry').onclick=()=>{parent.postMessage({type:'simulator:ready'},location.origin);poll()};
if(parent===window){$('connection').textContent='Apri Binotto Simulator dal catalogo di Binottoland su Telegram.';$('retry').hidden=false}
function updateHeader(){if(!data)return;const t=data.me;$('team-name').textContent=t?`${t.name} · LV ${1+Math.floor(t.xp/300)}`:'Il tuo posto al muretto';$('balance').textContent=t?money(t.cash):'';if($('connected-names')){$('connected-names').textContent=(data.online||[]).map(u=>u.name).join(' · ')||'Nessuno';$('connected-count').textContent='● Connessi '+(data.online||[]).length}}
function car(t){const c=t.colors,a=c[0],b=t.count>1?c[1]:a,d=t.count>2?c[2]:b;return `<svg viewBox="0 0 500 170" aria-label="Livrea scuderia" role="img"><defs><linearGradient id="body-light" x2="0" y2="1"><stop stop-color="#fff" stop-opacity=".3"/><stop offset=".45" stop-color="#fff" stop-opacity="0"/><stop offset="1" stop-color="#000" stop-opacity=".3"/></linearGradient></defs><g fill="#080d15" stroke="#556171" stroke-width="2"><rect x="85" y="25" width="55" height="33" rx="8"/><rect x="85" y="115" width="55" height="33" rx="8"/><rect x="350" y="20" width="62" height="39" rx="8"/><rect x="350" y="114" width="62" height="39" rx="8"/></g><g stroke="#a6b3c3" stroke-width="3"><path d="M115 45L175 85 115 130M380 40L315 85 380 135"/></g><path d="M50 85L155 70 225 45 360 50 395 85 360 120 225 125 155 100Z" fill="${a}"/><path d="M55 81L235 75 360 65 360 100 235 95 55 89Z" fill="${b}"/><rect x="62" y="43" width="17" height="86" rx="3" fill="${d}"/><rect x="404" y="37" width="22" height="97" rx="3" fill="${d}"/><ellipse cx="253" cy="85" rx="26" ry="17" fill="#11151b" stroke="${d}" stroke-width="4"/><circle cx="255" cy="85" r="9" fill="#e6e5e1"/><path d="M282 60L350 60 374 85 350 111 282 111" fill="none" stroke="${d}" stroke-width="4"/><path d="M50 85L155 70 225 45 360 50 395 85 360 120 225 125 155 100Z" fill="url(#body-light)"/></svg>`}
function render(){if(!data)return;for(const el of document.querySelectorAll('.split'))el._releaseDrag?.();disposePanels();updateHeader();$('navigation').innerHTML=['Paddock','Scuderia','Mercato','Box','Campionato','Evento','Libere','Qualifiche','Gara'].map(t=>button('tab',t,`data-tab="${t}"`,t===tab?'active':'')).join('');$('main').className=['Gara','Libere','Qualifiche'].includes(tab)?(tab==='Gara'?'racing':'racing sessions'):'';const pages={Paddock:paddock,Scuderia:team,Mercato:market,Box:()=>strategies()+telemetryPage(),Strategia:()=>strategies()+telemetryPage(),Campionato:championship,Evento:eventPage,Telemetria:telemetryPage,Libere:sessionsPage,Qualifiche:sessionsPage,Gara:race};$('main').innerHTML=pages[tab]();restoreDrafts();restoreChatDraft();const availability=document.querySelector('[data-form=proposal]');if(availability)updateAvailability(availability);if(tab==='Gara'){attachCanvas($('track'));installSplitters();updateRace()}else if(['Libere','Qualifiche'].includes(tab)){attachCanvas($('track'));updateSessions()}updateCommunity();updateEventBoard();disposePanels=installPanelLayouts($('main'),tab);persistView()}
function onboarding(){return `<div class="notice"><b>Il tuo primo campionato inizia qui.</b> Crea la scuderia con 10 milioni, ingaggia due piloti e tre tecnici, acquista il motore e iscriviti.${button('create','Crea la mia scuderia','','primary')}</div>`}
function paddock(){const t=data.me,i=Math.min(data.round,12),track=data.tracks[i],when=data.schedule?.dates[data.round];return `${!t?onboarding():''}<div class="paddock" ${!t?'style="height:calc(100% - 105px)"':''}><section class="hero-card"><img src="/simulator/assets/circuit-${i}.webp" alt="Panorama di ${track[0]}"><div class="hero-top"><span class="tag">STAGIONE ${data.season} / ROUND ${Math.min(data.round+1,13)}</span><span class="tag">${data.race?.active?'● IN DIRETTA':'IL PROSSIMO GRAN PREMIO'}</span></div><div class="eyebrow">${data.round>=13?'Stagione conclusa':when?date(when)+' · ORA ITALIANA':'Il calendario lo decidete voi'}</div><h2>${track[0]}</h2><p>${track[1].toFixed(3)} km &nbsp; / &nbsp; ${data.laps} giri &nbsp; / &nbsp; ${data.conditions?.forecast||'Previsione in preparazione'}</p><div class="row">${button('tab',data.race?.active?'Vai al muretto →':'Prepara la tua gara →',`data-tab="${data.race?.active?'Gara':'Box'}"`,'primary')}<span class="tag">${data.teams.filter(t=>t.enrolled).length} SCUDERIE ISCRITTE</span></div></section><section class="card team-summary"><div class="eyebrow">TEAM PRINCIPAL · ${esc(t?.principal||'Il tuo nome')}</div><h3>${esc(t?.name||'Una scuderia da costruire')}</h3><div class="car-stage">${car(t||{colors:['#f14e58','#ffd475','#fff'],count:2})}</div>${(t?.drivers||[null,null]).map((d,i)=>`<div class="driver-mini"><span><small>VETTURA 0${i+1}</small><br><b>${esc(d?.name||'Pilota da ingaggiare')}</b></span><strong>${d?.points||0} <small>PT</small></strong></div>`).join('')}<div class="subtle row"><small>${t?`Stipendi / GP · ${money(salary(t))}`:'Due piloti. Tre tecnici. Un obiettivo.'}</small>${button('tab','Gestisci','data-tab="Scuderia"')}</div></section><section class="card scroll-card"><div class="row"><h3>Bacheca eventi</h3>${button('tab','Calendario ↗','data-tab="Campionato"','quiet')}</div><div class="scroll-body" id="events"></div></section><section class="card scroll-card purple"><div class="row"><h3>Radio paddock</h3><span class="tag">CHAT DI GRUPPO</span></div><div class="scroll-body" id="chat"></div><form class="chat-form" data-form="chat"><input name="text" aria-label="Messaggio al paddock" maxlength="500" required placeholder="Scrivi alla community…"><button type="submit">Invia ↗</button></form></section></div>`}
function team(){const t=data.me;if(!t)return onboarding();const contracts=[...t.drivers.map((d,i)=>({role:'driver',label:'Pilota '+(i+1),person:d})),...Object.entries(t.crew).map(([role,person])=>({role,label:roles[role],person}))];return `<div class="row"><div><div class="eyebrow">${esc(t.principal)} · TEAM PRINCIPAL</div><h2>La tua scuderia.</h2></div><span class="tag">SALVATAGGIO PERSONALE ONLINE</span></div><div class="two"><section class="card"><h3>Design studio</h3><form data-form="identity"><label>Nome scuderia<input name="name" maxlength="32" required value="${esc(t.name)}"></label><div class="car-stage" id="livery">${car(t)}</div><div class="row"><label>Livrea<select name="count">${options({'1':'1 colore','2':'2 colori','3':'3 colori'},String(t.count))}</select></label>${t.colors.map((c,i)=>`<label>${['Base','Inserti','Dettagli'][i]}<input type="color" name="color${i}" value="${c}"></label>`).join('')}</div><output data-save-status role="status">Salvataggio automatico attivo</output></form></section><section class="card accent"><h3>Reparto sviluppo</h3><div class="stats"><div><small>POWER UNIT</small><b>${t.engine?.skill||'—'}</b></div><div><small>AERODINAMICA</small><b>LV ${t.aero}</b></div><div><small>TELAIO</small><b>LV ${t.chassis}</b></div></div><p class="muted">${esc(t.engine?.name||'Nessun motore: acquistalo nel mercato.')}</p>${['aero','chassis'].map((k,i)=>`<div class="row subtle"><span>${i?'Telaio':'Aerodinamica'} · LV ${t[k]}</span>${button('upgrade',money(t[k]*350000),`data-part="${k}" ${data.race?.active?'disabled':''}`)}</div>`).join('')}<div class="subtle"><small>Monte stipendi per GP</small><div class="metric">${money(salary(t))}</div><small>Addebitati alla partenza. Sponsorizzazione: 350.000 € a gara più 6.000 € per punto. Le modifiche sono bloccate durante la tua gara.</small></div></section></div><h3 class="subtle">Le cinque figure della scuderia</h3><div class="grid">${contracts.map(({role,label,person:p})=>`<article class="card contract"><span class="role">${label}</span><h3>${esc(p?.name||'Posizione aperta')}</h3><p class="muted">${p?`Competenza ${p.skill} · ${money(p.salary)} / GP`:'Scegli e ingaggia un professionista nel mercato condiviso.'}</p>${button('market-role',p?'Sostituisci':'Cerca nel mercato',`data-role="${role}"`)}</article>`).join('')}</div>`}
function market(){const t=data.me;if(!t)return onboarding();const level=1+Math.floor(t.xp/300);return `<div class="market-header"><div><div class="eyebrow">CONTRATTI CONDIVISI · RINNOVO ${date(data.marketRefresh)}</div><h2>Il mercato del paddock.</h2></div><span class="tag">IL TUO LIVELLO ${level}</span></div><div class="filters">${Object.entries(roles).map(([r,n])=>button('market-role',n,`data-role="${r}"`,r===marketRole?'active':'')).join('')}</div><p class="muted subtle">Ogni offerta è unica: quando una scuderia la acquista non è più disponibile per le altre. I contratti si rinnovano ogni giorno.</p><div class="grid">${data.market.filter(o=>o.role===marketRole).map(o=>`<article class="card contract ${o.sold?'sold':''}"><div class="row"><span class="role">${roles[o.role]}</span><span class="tag">LV ${o.tier}</span></div><h3>${esc(o.name)}</h3><div class="stats"><div><small>COMPETENZA</small><b>${o.skill}</b></div>${o.role==='driver'?`<div><small>COSTANZA</small><b>${o.consistency}</b></div><div><small>GOMMA RESIDUA</small><b>${o.tyres}</b></div>`:''}</div><p><b>${money(o.fee)}</b><br><small>${o.salary?money(o.salary)+' / GP':'Acquisto motore · nessuno stipendio'}</small></p>${button('hire',o.sold?'Contratto assegnato':o.tier>level?'Sbloccato al livello '+o.tier:'Ingaggia →',`data-id="${o.id}" ${o.sold||o.tier>level||data.race?.active?'disabled':''}`,o.sold?'':'primary')}</article>`).join('')}</div>`}
function strategyFields(st){return `<div class="form-grid"><label>Carico aerodinamico<input type="number" name="wing" min="0" max="100" value="${st.wing}" required></label><label>Ripartizione freno anteriore %<input type="number" name="brake" min="45" max="65" value="${st.brake}" required></label><label>Mescola iniziale / pit singolo<select name="compound">${options(compounds,st.compound)}</select></label><label>Ritmo<select name="pace">${options({save:'Conserva',normal:'Normale',push:'Spingi'},st.pace)}</select></label><label>Pit singolo · giro (se piano vuoto)<input type="number" name="pitLap" min="1" max="${data.laps||60}" value="${st.pitLap}" required></label><label>Pit di riserva · gomme residue %<input type="number" name="wearAt" min="10" max="80" value="${st.wearAt}" required></label><label>Carburante iniziale · kg<input type="number" name="fuel" min="10" max="110" value="${st.fuel}" required></label><label>Rifornimento al pit · kg<input type="number" name="refuel" min="0" max="110" value="${st.refuel}" required></label></div><details class="stint-plans" ${st.stops?.length?'open':''}><summary>Piano fino a 3 soste · giro 0 = non utilizzata</summary><small>Se compilato sostituisce il pit singolo. I rientri di sicurezza restano attivi; ogni sosta usa la prossima mescola e quantità del piano.</small>${[0,1,2].map(i=>{const p=st.stops?.[i];return `<div class="stint-row"><label>Sosta ${i+1} · giro<input name="stopLap${i}" type="number" min="0" max="${data.laps||60}" value="${p?.lap||0}"></label><label>Mescola<select name="stopCompound${i}">${options(compounds,p?.compound||'medium')}</select></label><label>Kg da aggiungere<input name="stopFuel${i}" type="number" min="0" max="110" value="${p?.refuel??30}"></label></div>`}).join('')}</details>`}
function strategies(){const t=data.me;if(!t)return onboarding();const track=data.tracks[Math.min(data.round,12)];return `<div class="eyebrow">PROSSIMO APPUNTAMENTO · ${track[0]}</div><h2>Box · assetto, strategia e telemetria.</h2><div class="notice">${track[1]} km · ${data.laps} giri · ${data.conditions?.forecast||'Previsione in preparazione'}. Il piano offline usa giro pit, soglia gomme e riserva carburante. Se sei al muretto puoi cambiarlo durante la gara. Offline: velocità media −5%.</div><div class="two">${t.strategies.map((st,i)=>`<section class="card ${i?'purple':'accent'}"><div class="eyebrow">VETTURA 0${i+1}</div><h3>${esc(t.drivers[i]?.name||'Pilota da ingaggiare')}</h3><form class="strategy-form" data-form="strategy" data-slot="${i}">${strategyFields(st)}<small>Consumo iniziale stimato: ${(data.engineering?.drivers?.[i]?.consumption||0).toFixed(2)} kg/giro. Peso, motore, carico e ritmo modificano consumo e gomme. Il pit avviene al passaggio del traguardo; la riserva automatica interviene sotto 1,7 giri di carburante.</small><output data-save-status role="status">Salvataggio automatico attivo</output></form></section>`).join('')}</div>`}
const proposalSlots=p=>p.slots||p.days.map(day=>({day,times:p.times}));
function qualifyingClock(time){if(!/^\d{2}:\d{2}$/.test(time||''))return '—';const [h,m]=time.split(':').map(Number),at=h*60+m;const fmt=n=>{n=(n+1440)%1440;return String(Math.floor(n/60)).padStart(2,'0')+':'+String(n%60).padStart(2,'0')};return fmt(at-30)+'–'+fmt(at-10)+(at<30?' (inizio il giorno prima)':'');}
function availabilityForm(t){const own=data.proposals.find(p=>p.author===t?.id),slots=own?proposalSlots(own):[],daily=own?.daily||Math.max(1,...slots.map(s=>s.times.length));return `<form data-form="proposal"><label>Disponibile a partire dal<input type="date" name="start" required value="${own?.start||new Date(Date.now()+86400000).toISOString().slice(0,10)}"></label><label>Gare per giornata selezionata<select name="daily">${options({'1':'1 gara al giorno (standard)','2':'2 gare al giorno'},String(daily))}</select></label><p class="muted">Spunta i giorni in cui puoi esserci e scegli l’orario di gara per ciascuno. Le qualifiche sono sempre 30 minuti prima e durano 20 minuti: confermi la disponibilità per entrambe.</p><div class="availability-week">${days.map((d,i)=>{const chosen=slots.find(s=>s.day===i);return `<div class="availability-day" data-day="${i}"><label class="day-toggle"><input type="checkbox" name="day" value="${i}" ${chosen?'checked':''}>${d}</label>${[0,1].map(n=>`<label data-race-slot="${n}">Gara ${n+1}<input type="time" name="time-${i}-${n}" value="${chosen?.times[n]|| (n?'22:30':'21:00')}" required><small data-qualifying>Qualifica ${qualifyingClock(chosen?.times[n]||(n?'22:30':'21:00'))}</small></label>`).join('')}</div>`}).join('')}</div><p class="muted">Almeno 90 minuti tra due gare. Orari Italia/Malta. Riformulare sostituisce la tua proposta e richiede nuovi voti.</p><button class="primary" type="submit" ${!t?.enrolled?'disabled':''}>Pubblica / riformula disponibilità</button><output data-save-status>Bozza conservata su questo dispositivo; pubblica per condividerla.</output></form>`;}
function updateAvailability(form){const daily=Number(form.elements.daily.value);for(const row of form.querySelectorAll('[data-day]')){const active=row.querySelector('[name=day]').checked;row.classList.toggle('selected',active);for(const label of row.querySelectorAll('[data-race-slot]')){const second=Number(label.dataset.raceSlot)===1;label.hidden=second&&daily===1;const input=label.querySelector('input');input.disabled=!active||(second&&daily===1);label.querySelector('[data-qualifying]').textContent='Qualifica '+qualifyingClock(input.value);}}}
function championship(){const t=data.me,registered=data.teams.filter(t=>t.enrolled),required=Math.max(2,registered.length);return `<div class="row"><div><div class="eyebrow">STAGIONE ${data.season} · ${registered.length} ISCRITTI</div><h2>Il vostro campionato.</h2></div>${data.round>=13?button('next-season','Apri la prossima stagione','','primary'):!data.schedule&&t?button('enroll',t.enrolled?'Ritira iscrizione':'Iscrivi la scuderia',`data-value="${!t.enrolled}" ${!ready(t)?'disabled':''}`,'primary'):''}</div>${!data.schedule?`<div class="notice">Completa organico e motore per iscriverti. Servono i voti di tutti i ${required} iscritti (minimo due scuderie) sulla stessa proposta. Il voto unanime chiude le iscrizioni e pubblica il calendario ufficiale. Gli orari sono italiani (Europe/Rome).</div><div class="two"><section class="card"><h3>Quando puoi partecipare?</h3>${availabilityForm(t)} </section><section class="card"><h3>Disponibilità e proposte del gruppo</h3><p class="muted">Confrontate gli orari, riformulate se serve, poi votate un unico calendario. Pubblicare una disponibilità non equivale a votare.</p>${data.proposals.length?data.proposals.map(p=>`<article class="event-proposal"><b>${esc(p.name)}</b><small> · dal ${esc(p.start)}</small>${proposalSlots(p).map(slot=>`<p><strong>${days[slot.day]}</strong> ${slot.times.map(time=>`<span class="availability-summary">Qualifica ${qualifyingClock(time)} · <b>Gara ${esc(time)}</b></span>`).join('')}</p>`).join('')}<div class="row"><span class="tag">${p.votes} / ${required} VOTI</span>${button('vote',p.myVote?'Il tuo voto ✓':'Vota questo calendario e la chiusura',`data-id="${p.id}" ${!t?.enrolled?'disabled':''}`,p.myVote?'active':'')}</div></article>`).join(''):'<p class="muted">Nessuna disponibilità ancora pubblicata.</p>'}</section></div>`:`<div class="notice">Calendario approvato · ${data.schedule.participants.length} scuderie · Le gare partono automaticamente, anche se nessuno è collegato.</div><div class="calendar">${data.tracks.map((tr,i)=>`<article><img src="/simulator/assets/circuit-${i}.webp" alt=""><span class="eyebrow">${String(i+1).padStart(2,'0')} ${i<data.round?'· CONCLUSA':''}</span><b>${tr[0]}</b><small>Gara ${date(data.schedule.dates[i])}<br>Qualifiche ${date(data.schedule.dates[i]-1800000)} – ${date(data.schedule.dates[i]-600000)}</small></article>`).join('')}</div>`}<div class="two subtle"><section class="card"><h3>Classifica costruttori</h3><table><thead><tr><th>Pos</th><th>Scuderia</th><th>Punti</th></tr></thead><tbody>${[...data.teams].sort((a,b)=>b.points-a.points).map((t,i)=>`<tr><td>${i+1}</td><td>${esc(t.name)}<br><small>${esc(t.principal)}</small></td><td>${t.points}</td></tr>`).join('')}</tbody></table></section><section class="card"><h3>Risultati ufficiali</h3>${data.results.length?data.results.map(r=>`<details><summary>${data.tracks[r.round][0]} · stagione ${r.season} · ${date(r.at)}</summary><table>${r.rows.map(c=>`<tr><td>${c.position}</td><td>${esc(c.name)}<br><small>${esc(c.teamName)}</small></td><td>${c.dnf?'RIT':c.points+' pt'}</td></tr>`).join('')}</table></details>`).join(''):'<p class="muted">Le classifiche compariranno al termine delle gare.</p>'}</section></div>`}
function race(){const r=data.race,i=r?.round??Math.min(data.round,12);return `<div class="race-toolbar"><h2>${data.tracks[i][0]} <span class="tag">${r?.active?'● LIVE':r?'RISULTATI':'IN ATTESA'}</span></h2><div>${button('camera',followCamera?'Vista circuito':'Segui pilota')}${button('camera-reset','Centra')} </div></div><div class="race-top"><div class="track-wrap"><canvas id="track" aria-label="Gara vista dall’alto"></canvas><div class="track-hud"><span id="lap-hud"></span><span>${r?.wet?'PIOGGIA':'ASCIUTTO'} · ${data.tracks[i][1]} KM · ${r?.laps||data.laps} GIRI · ${r?.conditions?.trackTemp?.toFixed(0)||data.conditions?.trackTemp||'—'}°C PISTA</span></div><div class="track-help">SELEZIONA UN PILOTA · ROTELLA PER ZOOM · TRASCINA LA VISTA</div></div><div class="split vertical" role="separator" tabindex="0" aria-label="Larghezza classifica" aria-orientation="vertical" id="split-width"></div><aside class="card race-board"><h3>CLASSIFICA LIVE</h3><div id="leaders"></div><div id="race-events" class="subtle"></div></aside></div><div class="split horizontal" role="separator" tabindex="0" aria-label="Altezza pannelli piloti" aria-orientation="horizontal" id="split-height"></div><div class="driver-controls">${[0,1].map(i=>`<section class="card live-card" id="live-${i}"></section>`).join('')}</div>`}
function updateRace(){const r=data.race;if(!$('leaders'))return;const cars=[...(r?.cars||[])].sort((a,b)=>(a.dnf-b.dnf)||(a.finished&&b.finished?a.finished-b.finished:b.progress-a.progress));$('lap-hud').textContent=r?`GIRO ${Math.min(r.laps||data.laps,1+Math.floor(cars[0]?.progress||0))} / ${r.laps||data.laps}`:'NESSUNA GARA IN CORSO';$('leaders').innerHTML=cars.length?cars.map((c,i)=>`<button class="leader ${follow===c.id?'selected':''}" data-action="follow" data-id="${c.id}"><span style="color:${c.colors[0]}">${i+1}</span><span><b>${esc(c.name)}</b><small>${esc(c.teamName)} · ${c.compound.toUpperCase()}</small></span><span>${c.dnf?'RIT':c.finished?'ARRIVO':i?'≈ +'+((cars[0].progress-c.progress)*(c.lastLap||data.engineering?.drivers?.[0]?.lapEstimate||90)).toFixed(1)+'s':'LEADER'}</span></button>`).join(''):'<p class="empty">La gara parte all’orario approvato. Iscriviti dal Campionato.</p>';$('race-events').innerHTML=(r?.events||[]).slice(0,5).map(e=>`<div class="feed-item">${esc(e.text)}</div>`).join('');for(let i=0;i<2;i++){const c=r?.cars.find(c=>c.own&&c.slot===i),el=$('live-'+i);if(!c){el.innerHTML=`<div class="eyebrow">VETTURA 0${i+1}</div><h3>${esc(data.me?.drivers[i]?.name||'Pilota da ingaggiare')}</h3><p class="muted">${data.me?.enrolled?'In attesa della partenza automatica.':'Completa la scuderia e iscriviti al campionato.'}</p>${button('tab','Piano gara','data-tab="Box"')}`;continue}el.innerHTML=`<div class="row"><h3>${esc(c.name)}</h3><span class="tag">${c.finished?'ARRIVATO':c.dnf?'RITIRATO':c.pitTime?'AI BOX':c.compound.toUpperCase()}</span></div><div class="telemetry"><div><small>CARBURANTE</small><b>${c.fuel.toFixed(1)} kg</b></div><div><small>CONSUMO/GIRO</small><b>${(c.consumption||0).toFixed(2)}</b></div><div><small>GOMMA RESIDUA</small><b>${c.wear.toFixed(0)}%</b></div><div><small>TEMP. GOMME</small><b>${(c.temperature??90).toFixed(0)}°C</b></div><div><small>AUTONOMIA</small><b>${c.consumption?(c.fuel/c.consumption).toFixed(1):'—'} giri</b></div><div><small>VELOCITÀ</small><b>${Math.round(c.speed)} km/h</b></div></div><div class="meter"><i style="width:${c.wear}%;background:${c.wear<30?'#ff8175':'var(--teal)'}"></i></div><div class="live-actions">${button('live-plan','Box',`data-slot="${i}" ${!r.active||c.finished||c.dnf?'disabled':''}`)}${button('pit',c.pitRequested?'Annulla pit':'BOX a fine giro',`data-slot="${i}" ${!r.active||c.finished||c.dnf?'disabled':''}`,'primary')}<small>Grip ${(c.grip??100).toFixed(0)}% · Pit ${c.pits} · ${c.strategy.pace==='push'?'Spingi':c.strategy.pace==='save'?'Conserva':'Normale'}</small></div><small>Carburante al traguardo senza altri rifornimenti: ${(c.fuelAtFinish??0).toFixed(1)} kg</small><div class="offline">${c.offline?'Strategia offline · velocità −5%':'Muretto collegato · pieno controllo'}${c.traffic?' · Nel traffico':''}${c.lastLap?' · Ultimo giro '+c.lastLap.toFixed(1)+' s':''}</div>`}}
function updateCommunity(){if($('events'))$('events').innerHTML=data.events.length?data.events.map(e=>`<div class="feed-item"><time>${date(e.at)}</time>${esc(e.text)}</div>`).join(''):'<p class="muted">Benvenuto nel primo campionato della community.</p>';if($('chat')){const el=$('chat'),bottom=el.scrollHeight-el.scrollTop-el.clientHeight<50;el.innerHTML=data.chat.length?data.chat.map(m=>`<article class="chat-message"><b>${esc(m.name)} · ${esc(m.team)}</b><p>${esc(m.text)}</p></article>`).join(''):'<p class="muted">Strategie, rivalità e chiacchiere dal paddock.</p>';if(bottom)el.scrollTop=el.scrollHeight}}
function openDialog(html){$('modal').innerHTML=button('close','×','','close')+html;$('modal').showModal();restoreDrafts()}
function getStrategy(form){const fd=new FormData(form),s={};for(const k of ['wing','brake','pitLap','wearAt','fuel','refuel'])s[k]=Number(fd.get(k));s.compound=fd.get('compound');s.pace=fd.get('pace');s.stops=[0,1,2].map(i=>({lap:Number(fd.get('stopLap'+i)||0),compound:fd.get('stopCompound'+i)||'medium',refuel:Number(fd.get('stopFuel'+i)||0)})).filter(p=>p.lap>0);return s}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b||b.disabled)return;const a=b.dataset.action;if(a.startsWith('session-')){if(a==='session-follow'){follow=b.dataset.id;followCamera=true;return}await flushAutoSaves();await commandTail;if([...autoJobs.values()].some(j=>j.body.action==='session-setup'&&j.body.mode===testingMode())){toast('Attendi il salvataggio dell’assetto prima di inviare il comando.');return}await command({action:a,mode:testingMode(),slot:Number(b.dataset.slot||0)},{quiet:true});updateSessions();return}if(a==='exit'){await exitGame();return}if(a==='fullscreen'){if(document.fullscreenElement)document.exitFullscreen?.();else document.documentElement.requestFullscreen?.().catch(()=>toast('Usa lo schermo intero di Telegram o F11.'));return}if(a==='close'){await flushAutoSaves();return $('modal').close()}if(a==='tab'){await flushAutoSaves();tab=b.dataset.tab;render();presence();return}if(a==='market-role'){tab='Mercato';marketRole=b.dataset.role;render();return}if(a==='create')return command({action:'create'});if(a==='upgrade')return command({action:'upgrade',part:b.dataset.part});if(a==='enroll')return command({action:'enroll',enrolled:b.dataset.value==='true'});if(a==='vote')return command({action:'vote',proposal:b.dataset.id});if(a==='next-season')return command({action:'next-season'});if(a==='hire'){const o=data.market.find(o=>o.id===b.dataset.id);openDialog(`<div class="eyebrow">NUOVO CONTRATTO</div><h2>${esc(o.name)}</h2><p>Ingaggio ${money(o.fee)}${o.salary?' · stipendio '+money(o.salary)+' / GP':''}.</p>${o.role==='driver'?`<p class="muted">Scegli il posto. L’eventuale contratto precedente termina senza rimborso.</p><div class="two">${[0,1].map(i=>button('confirm-hire','Vettura '+(i+1)+' · '+esc(data.me.drivers[i]?.name||'Libera'),`data-id="${o.id}" data-slot="${i}"`,'primary')).join('')}</div>`:button('confirm-hire','Conferma ingaggio',`data-id="${o.id}" data-slot="0"`,'primary')}`);return}if(a==='confirm-hire'){$('modal').close();return command({action:'hire',offer:b.dataset.id,slot:Number(b.dataset.slot)})}if(a==='follow'){follow=b.dataset.id;followCamera=true;resetCamera();render();return}if(a==='camera'){followCamera=!followCamera;resetCamera();render();return}if(a==='camera-reset'){resetCamera();return}if(a==='live-plan'){const slot=Number(b.dataset.slot),c=data.race.cars.find(c=>c.own&&c.slot===slot);openDialog(`<h2>${esc(c.name)} · Piano live</h2><form data-form="live" data-slot="${slot}">${strategyFields(c.strategy)}<p class="muted">Carico aerodinamico e freni sono regolazioni gestionali. La mescola cambia al prossimo pit; il carburante iniziale non modifica quello già nel serbatoio.</p><output data-save-status role="status">Le modifiche vengono trasmesse automaticamente</output></form>`);return}if(a==='pit'){const slot=Number(b.dataset.slot),c=data.race.cars.find(c=>c.own&&c.slot===slot);return command({action:'live',slot,strategy:c.strategy,pit:!c.pitRequested},{quiet:true})}});
document.addEventListener('submit',async e=>{const f=e.target.closest('[data-form]');if(!f)return;e.preventDefault();const fd=new FormData(f),type=f.dataset.form;if(type==='chat'){if(chatSending)return;const text=String(fd.get('text')||'').trim();if(!text)return;chatSending=true;const submit=f.querySelector('button');submit.disabled=true;const requestId=chatPending?.text===text?chatPending.id:crypto.randomUUID();chatPending={text,id:requestId};saveChatDraft(text);const ok=await command({action:'chat',text,requestId},{quiet:true});chatSending=false;if(submit.isConnected)submit.disabled=false;if(ok){chatPending=null;const input=document.querySelector('[data-form=chat] input');if(input?.value.trim()===text){input.value='';saveChatDraft('')}updateCommunity();formNotice(document.querySelector('[data-form=chat]'),'Messaggio inviato e salvato ✓');toast('Messaggio inviato e salvato ✓')}return}if(type==='identity')return command({action:'identity',name:fd.get('name'),count:Number(fd.get('count')),colors:[0,1,2].map(i=>fd.get('color'+i))});if(type==='strategy')return command({action:'strategy',slot:Number(f.dataset.slot),strategy:getStrategy(f)});if(type==='live'){const slot=Number(f.dataset.slot),strategy=getStrategy(f),c=data.race.cars.find(c=>c.own&&c.slot===slot);$('modal').close();return command({action:'live',slot,strategy,pit:c.pitRequested},{quiet:true})}if(type==='session-setup'){rememberDraft(f);return flushAutoSaves()}if(type==='proposal')return command({action:'proposal',slots:fd.getAll('day').map(Number).map(day=>({day,times:[0,1].slice(0,Number(fd.get('daily'))).map(n=>fd.get('time-'+day+'-'+n))})),start:fd.get('start')})});
for(const event of ['input','change'])document.addEventListener(event,e=>{const form=e.target.closest('[data-form]');if(form){if(form.dataset.form==='proposal')updateAvailability(form);rememberDraft(form)}});
document.addEventListener('input',e=>{const form=e.target.closest('[data-form="identity"]');if(!form)return;identityDirty=true;const fd=new FormData(form);$('livery').innerHTML=car({count:Number(fd.get('count')),colors:[0,1,2].map(i=>fd.get('color'+i))})});
function installSplitters(){
 const root=document.documentElement,mode=innerWidth<=700?'phone':innerWidth<=850?'tablet':'desktop';
 for(const [id,key,axis] of [['split-width','side','clientX'],['split-height','bottom','clientY']]){
  const el=$(id);if(!el)continue;el._releaseDrag?.();
  const bounds=()=>{const container=key==='side'?document.querySelector('.race-top'):$('main');const available=(key==='side'?container?.clientWidth:container?.clientHeight)||(key==='side'?innerWidth:innerHeight-100);return {min:Math.min(key==='side'?110:90,available*.3),max:Math.max(60,Math.min(key==='side'?600:500,available-(key==='side'?150:160)))}};
  const storage='simulator-layout-'+mode+'-'+key;
  const current=()=>parseFloat(getComputedStyle(root).getPropertyValue('--'+key))||(key==='side'?220:180);
  const change=value=>{const b=bounds(),n=Math.round(Math.max(b.min,Math.min(b.max,value)));root.style.setProperty('--'+key,n+'px');el.setAttribute('aria-valuenow',n);el.setAttribute('aria-valuemin',Math.round(b.min));el.setAttribute('aria-valuemax',Math.round(b.max));try{localStorage.setItem(storage,n)}catch{}};
  let initial=current();try{initial=Number(localStorage.getItem(storage)||localStorage.getItem('simulator-layout-'+key))||initial}catch{}change(initial);
  let drag=null;
  const move=e=>{if(drag&&e.pointerId===drag.pointer)change(drag.size+drag.at-e[axis])};
  const end=()=>{drag=null;window.removeEventListener('pointermove',move);window.removeEventListener('pointerup',end);window.removeEventListener('pointercancel',end);document.body.classList.remove('panel-dragging')};el._releaseDrag=end;
  el.onpointerdown=e=>{if(e.button!==0)return;e.preventDefault();el.focus({preventScroll:true});drag={at:e[axis],size:current(),pointer:e.pointerId};try{el.setPointerCapture(e.pointerId)}catch{}document.body.classList.add('panel-dragging');window.addEventListener('pointermove',move);window.addEventListener('pointerup',end);window.addEventListener('pointercancel',end)};
  el.onlostpointercapture=end;
  el.onkeydown=e=>{const keys=key==='side'?['ArrowLeft','ArrowRight']:['ArrowUp','ArrowDown'];if(keys.includes(e.key)){e.preventDefault();change(current()+(e.key===keys[0]?10:-10))}};
 }
}
window.addEventListener('pagehide',()=>{persistView();persistAutoDrafts();if(token)api({action:'presence',visible:false},{keepalive:true}).catch(()=>{})});
function frame(){if(opened&&!document.hidden){if(tab==='Gara')draw(data,follow,followCamera,received);else if(['Libere','Qualifiche'].includes(tab))draw(testingData(),follow,followCamera,received);}requestAnimationFrame(frame)}requestAnimationFrame(frame);

const lapTime=n=>n?Math.floor(n/60)+':'+(n%60).toFixed(3).padStart(6,'0'):'—';
const clock=n=>Math.floor(Math.max(0,n)/60000)+':'+String(Math.floor(Math.max(0,n)/1000)%60).padStart(2,'0');
function testingMode(){return tab==='Libere'?'practice':'qualifying'}
function testingData(){const ss=data.sessions,mode=testingMode(),v=ss?.[mode];return {...data,race:{round:data.round,active:mode==='practice'?v?.cars.some(c=>c.onTrack&&c.speed>0):v?.active,cars:(v?.cars||[]).map(c=>({...c,pitTime:c.onTrack?0:1}))}}}
function sessionsPage(){return `<div class="session-layout"><div class="row"><div><div class="eyebrow">${esc(data.tracks[Math.min(data.round,12)][0])} · ${tab==='Libere'?'LIBERE DEL CAMPIONATO':'SESSIONE CONDIVISA'}</div><h2>${tab==='Libere'?'Prove libere':'Qualifiche'}</h2></div><strong class="metric" id="session-clock"></strong></div><div class="session-stage"><section class="track-wrap"><canvas id="track" aria-label="Circuito della sessione"></canvas><div class="track-overlay">${button('camera-reset','Centra pista')} ${button('tab','Box','data-tab="Box"')}</div></section><aside class="card scroll-card"><h3>Tempi sul giro</h3><div class="scroll-body" id="session-leaders"></div></aside></div><div id="session-info" class="notice"></div><div class="two session-drivers" id="session-drivers"></div></div>`}
function updateSessions(){if(!$('session-clock')||!data.sessions)return;const ss=data.sessions,mode=testingMode(),v=ss[mode],available=ss.eligible&&(mode==='practice'?v.available&&v.remaining>0:v.active);$('session-clock').textContent=mode==='qualifying'&&ss.start>data.now?'Tra '+clock(ss.start-data.now):clock(v.remaining);$('session-info').textContent=mode==='practice'?(ss.raceDay?'Libere chiuse oggi: è giorno di gara.':!ss.eligible?'Libere disponibili dopo la chiusura delle iscrizioni e la pubblicazione del calendario.':`30 minuti totali per Gran Premio, senza rinnovo giornaliero. ${v.running?'Tempo in corso':'Tempo fermo'}. Alla chiusura il tempo si ferma; interruzione di rete rilevata entro 10 s. Giro di uscita non cronometrato.`):(v.active?'Qualifiche in corso: tutti girano insieme. Dopo 10 s senza connessione la vettura torna ai box; il giro incompleto è annullato.':ss.at?`${v.finished?'Qualifiche concluse':'Qualifiche programmate'}: ${date(ss.start)} – ${date(ss.end)}. Gara ${date(ss.at)}. Chi non registra un tempo parte dietro.`:'Il calendario deve essere approvato. Le qualifiche iniziano 30 minuti prima della gara e durano 20 minuti.');
 const cars=[...v.cars].sort((a,b)=>(a.best||Infinity)-(b.best||Infinity));$('session-leaders').innerHTML=cars.length?cars.map((c,i)=>`<button class="leader" data-action="session-follow" data-id="${esc(c.id)}"><span>${i+1}</span><span><b>${esc(c.name)}</b><small>${c.onTrack?'IN PISTA':'AI BOX'} · ${esc(c.teamName)}</small></span><span>${lapTime(c.best)}</span></button>`).join(''):'<p class="empty">Nessun giro registrato.</p>';
 updatePitwall(v,mode,available);}
function getSessionSetup(f){const n=k=>Number(f.elements[k].value);return {wing:n('wing'),brake:n('brake'),fuel:n('fuel'),stintLaps:n('stintLaps'),compound:f.elements.compound.value,pace:f.elements.pace.value};}
function sessionFields(st){return `<div class="session-settings"><label>Carico aerodinamico<input name="wing" type="number" min="0" max="100" required value="${st.wing}"></label><label>Freni anteriori %<input name="brake" type="number" min="45" max="65" required value="${st.brake}"></label><label>Carburante uscita · kg<input name="fuel" type="number" min="10" max="110" required value="${st.fuel}"></label><label>Giri lanciati<input name="stintLaps" type="number" min="1" max="20" required value="${st.stintLaps}"></label><label>Mescola<select name="compound">${options(compounds,st.compound)}</select></label><label>Ritmo<select name="pace">${options({save:'Conserva',normal:'Normale',push:'Spingi'},st.pace)}</select></label></div><output data-save-status role="status">Assetto sessione · salvataggio automatico</output>`;}
function updatePitwall(v,mode,available){const root=$('session-drivers'),key=mode+':'+data.sessions.event;if(root.dataset.session!==key){root.dataset.session=key;replacePanelContent(root,[0,1].map(slot=>`<section class="card session-car" data-car-slot="${slot}"><div class="eyebrow">MURETTO · VETTURA ${slot+1} · ${mode==='practice'?'LIBERE':'QUALIFICHE'}</div><div class="row"><h3>${esc(data.me?.drivers[slot]?.name||'Pilota '+(slot+1))}</h3><span class="tag" data-session-status></span></div><div class="telemetry" data-session-telemetry></div><div class="row session-actions" data-session-actions></div><p class="muted" data-session-reason></p><form data-form="session-setup" data-mode="${mode}" data-event="${data.sessions.event}" data-slot="${slot}">${sessionFields(data.sessions.setups?.[mode]?.[slot]||{wing:50,brake:55,fuel:30,stintLaps:3,compound:'medium',pace:'normal'})}</form><details><summary>Giri registrati in questa sessione</summary><div data-session-history></div></details></section>`).join(''));restoreDrafts();}
 for(const card of root.querySelectorAll('[data-car-slot]')){const slot=Number(card.dataset.carSlot),c=v.cars.find(c=>c.own&&c.slot===slot),f=card.querySelector('form'),st=data.sessions.setups?.[mode]?.[slot];card.querySelector('[data-session-status]').textContent=c?.onTrack?(c.pitRequested?'RIENTRO A FINE GIRO':c.outLap?'GIRO DI USCITA':`GIRO LANCIATO ${(c.runLaps||0)+1} / ${c.targetLaps||'—'}`):'AI BOX';
 const values=[['Migliore',lapTime(c?.best)],['Ultimo giro',lapTime(c?.lastLap)],['Velocità',c?Math.round(c.speed)+' km/h':'—'],['Carburante',c?c.fuel.toFixed(1)+' kg':'—'],['Consumo/giro',c?(c.consumption||0).toFixed(2)+' kg':'—'],['Autonomia',c?.consumption?(c.fuel/c.consumption).toFixed(1)+' giri':'—'],['Gomma residua',c?c.wear.toFixed(0)+'%':'—'],['Temperatura',c?.temperature?c.temperature.toFixed(0)+' °C':'—'],['Grip',c?.grip?c.grip.toFixed(0)+'%':'—']];card.querySelector('[data-session-telemetry]').innerHTML=values.map(([label,value])=>`<div><small>${label}</small><b>${value}</b></div>`).join('');
 card.querySelector('[data-session-actions]').innerHTML=button(c?.onTrack?'session-pit':'session-start',c?.onTrack?'Rientra a fine giro':'Esci in pista',`data-slot="${slot}" ${!available||c?.pitRequested?'disabled':''}`,'primary')+(c?.onTrack?button('session-extend','Allunga +1 giro',`data-slot="${slot}" ${!available?'disabled':''}`):'')+(mode==='practice'?button(v.running?'session-pause':'session-resume',v.running?'Pausa libere':'Riprendi libere',!available?'disabled':''):'');
 card.querySelector('[data-session-reason]').textContent=(c?.reason?c.reason+'. ':'')+(c?.onTrack?'Ritmo e ripartizione frenante regolabili in pista. Carico, gomme, benzina e programma al rientro.':'Prepara questa uscita: un giro iniziale non cronometrato, poi i giri lanciati scelti. Il piano gara resta separato.');
 if(st&&!drafts.has(formKey(f))&&!f.contains(document.activeElement))for(const [name,value] of Object.entries(st))if(f.elements[name])f.elements[name].value=value;
 for(const el of f.elements)if(el.name)el.disabled=!available||!!c?.onTrack&&['wing','fuel','compound','stintLaps'].includes(el.name);
 card.querySelector('[data-session-history]').innerHTML=(c?.history||[]).slice(0,5).map(h=>`<p>${lapTime(h.time)} · ${h.consumption.toFixed(2)} kg/giro · usura ${h.wearPerLap.toFixed(1)}% · carico ${h.wing} · freni ${h.brake}% · ${esc(h.compound)}</p>`).join('')||'<p>Nessun giro lanciato completato.</p>';
 }}

function telemetryPage(){const report=data.engineering;if(!report||report.drivers.every(d=>!d))return '<div class="notice">Completa piloti, tecnici e motore per ricevere le previsioni.</div>';return `<div class="row"><h2>Telemetria e reparto tecnico</h2>${button('tab','Vai alle libere','data-tab="Libere"')}</div><div class="notice">Obiettivo durata 35–45 minuti in condizioni normali · Gara: ${report.laps} giri · ${report.distance.toFixed(1)} km · limite massimo ${report.maxMinutes} minuti. Le durate e i consumi sotto sono stime del modello, non risultati garantiti. I dati registrati sono disponibili dopo i giri delle libere ufficiali.</div><div class="two">${report.drivers.map((d,i)=>d?`<section class="card"><div class="eyebrow">VETTURA ${i+1}</div><h3>${esc(d.name)}</h3><div class="stats"><div><small>CONSUMO / GIRO</small><b>${d.consumption.toFixed(2)} kg</b></div><div><small>USURA / GIRO</small><b>${d.wearPerLap.toFixed(1)}%</b></div><div><small>DURATA GARA STIMATA</small><b>≈ ${d.raceMinutes.toFixed(0)} min</b></div></div><p>Giro stimato ${lapTime(d.lapEstimate)} · autonomia iniziale ${d.fuelRange} giri · circa ${d.stops} soste.</p><p class="muted">${esc(d.confidence||'Stima preliminare')} · margine indicativo ±${((d.uncertainty||.1)*100).toFixed(0)}% · senza traffico. ${d.dnf?'⚠ Piano insufficiente per terminare.':`Carburante previsto all’arrivo: ${(d.finishFuel||0).toFixed(1)} kg.`}</p><div class="projection-comparison">${(d.alternatives||[]).map(a=>`<span>${esc(a.label)}<br><b>${a.dnf?'Non termina':(a.seconds/60).toFixed(1)+' min'}</b> · soste effettive ${a.stops}</span>`).join('')}</div>${d.advice.map(a=>`<article class="feed-item"><b>${esc(a.role)}${a.name?' · '+esc(a.name):''}</b><p>${esc(a.text)}</p></article>`).join('')}<h3>Giri registrati</h3>${d.measured.length?`<table><thead><tr><th>Tempo</th><th>kg/giro</th><th>Usura/giro</th><th>Carico</th></tr></thead><tbody>${d.measured.map(h=>`<tr><td>${lapTime(h.time)}</td><td>${h.consumption.toFixed(2)}</td><td>${h.wearPerLap.toFixed(1)}%</td><td>${h.wing}</td></tr>`).join('')}</tbody></table>`:'<p class="muted">Nessun giro registrato: stime preliminari dei tecnici.</p>'}</section>`:'').join('')}</div>`}
function standingsTable(rows,drivers=false){return `<table><thead><tr><th>Pos.</th><th>${drivers?'Pilota / Scuderia':'Scuderia'}</th><th>Punti</th><th>Premio</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${r.position}</td><td>${esc(r.name)}${drivers?'<br><small>'+esc(r.teamName)+'</small>':''}</td><td><b>${r.points}</b>${r.points!==r.confirmed?'<small> ('+r.confirmed+' confermati)</small>':''}</td><td>${r.reward?money(r.reward):'—'}</td></tr>`).join('')}</tbody></table>`}
function eventPage(){return `<div id="event-live"></div><section class="card subtle"><h3>Premi di fine campionato · cassa unica</h3><p class="muted">Importi di gioco. Premi piloti e costruttori sono sommati e accreditati unicamente alla scuderia. Spareggi per numero di migliori piazzamenti.</p><table><thead><tr><th>Pos.</th><th>Scuderia</th><th>Pilota</th></tr></thead><tbody>${(data.prizes?.teams||[]).map((n,i)=>`<tr><td>${i+1}</td><td>${money(n)}</td><td>${money(data.prizes.drivers[i])}</td></tr>`).join('')}</tbody></table></section><h2 class="subtle">Archivio campionati</h2>${(data.archives||[]).map(a=>`<details class="card"><summary>Stagione ${a.season} · conclusa ${date(a.ended)}</summary><h3>Costruttori</h3>${standingsTable(a.standings.teams)}<h3>Piloti</h3>${standingsTable(a.standings.drivers,true)}<h3>Gare archiviate</h3>${a.results.map(r=>`<details><summary>${esc(data.tracks[r.round][0])} · ${date(r.at)}</summary><table>${r.rows.map(c=>`<tr><td>${c.position}</td><td>${esc(c.name)}</td><td>${esc(c.teamName)}</td><td>${c.points} pt</td></tr>`).join('')}</table></details>`).join('')}</details>`).join('')||'<p class="muted">Il campionato verrà archiviato automaticamente dopo la tredicesima gara.</p>'}`}
function updateEventBoard(){const el=$('event-live');if(!el)return;const t=data.championship||{drivers:[],teams:[]};el.innerHTML=`<div class="row"><h2>Campionato · stagione ${data.season}</h2><span class="tag">${data.schedule?'ISCRIZIONI CHIUSE':'ISCRIZIONI APERTE'}</span></div><p>${t.provisional?'Classifiche LIVE provvisorie: includono i punti della posizione attuale.':'Classifiche ufficiali dei Gran Premi conclusi.'} Punti gara: 25–18–15–12–10–8–6–4–2–1.</p><section class="card"><h3>Scuderie iscritte</h3><div class="grid">${data.teams.filter(t=>data.schedule?data.schedule.participants.includes(t.id):t.enrolled).map(t=>`<div><b>${esc(t.name)}</b><small> · ${esc(t.principal)}</small><p>${t.drivers.map(d=>esc(d?.name||'Posto libero')).join(' / ')}</p></div>`).join('')||'Nessun iscritto.'}</div></section>${data.schedule?`<section class="card subtle"><h3>Calendario ufficiale</h3><table><thead><tr><th>GP</th><th>Qualifiche</th><th>Gara</th><th>Stato</th></tr></thead><tbody>${data.schedule.dates.map((at,i)=>`<tr><td>${esc(data.tracks[i][0])}</td><td>${date(at-1800000)}</td><td>${date(at)} · ${data.trackLaps?.[i]||data.laps} giri</td><td>${i<data.round?'Conclusa':i===data.round&&data.race?.active?'LIVE':'In programma'}</td></tr>`).join('')}</tbody></table></section>`:'<div class="notice">Il calendario diventa ufficiale quando tutti gli iscritti votano la stessa proposta: quel voto chiude anche le iscrizioni. '+button('tab','Vai alla votazione','data-tab="Campionato"')+'</div>'}<div class="two subtle"><section class="card"><h3>Classifica piloti</h3>${standingsTable(t.drivers,true)}</section><section class="card"><h3>Classifica scuderie</h3>${standingsTable(t.teams)}</section></div>`}

window.addEventListener('resize',()=>{if(tab==='Gara'&&$('split-width'))installSplitters()});

// The host sends {system, content} objects, not a numeric inset. Keep both layers.
function applySimulatorInsets(insets={}){for(const side of ['top','bottom','left','right']){const value=insets[side],valid=n=>Number.isFinite(n)?Math.max(0,Math.min(180,n)):0;const n=typeof value==='number'?valid(value):valid(value?.system)+valid(value?.content);document.documentElement.style.setProperty('--safe-'+side,n+'px');}}
function fitSimulatorViewport(){const height=Math.min(innerHeight,window.visualViewport?.height||innerHeight);document.documentElement.style.setProperty('--simulator-height',Math.max(1,height)+'px');}
let navigatingBack=false;
async function exitGame(){persistView();persistAutoDrafts();await flushAutoSaves();await commandTail;persistAutoDrafts();if(token)api({action:'presence',visible:false},{keepalive:true}).catch(()=>{});parent.postMessage({type:'arcade:exit'},location.origin);}
async function navigateBack(){if(navigatingBack)return;navigatingBack=true;try{if($('modal').open){await flushAutoSaves();$('modal').close();return}const connected=document.querySelector('.connected[open]');if(connected){connected.open=false;return}if(opened&&tab!=='Paddock'){await flushAutoSaves();tab='Paddock';render();return}await exitGame();}finally{navigatingBack=false}}
$('modal').addEventListener('cancel',e=>{e.preventDefault();navigateBack()});
window.visualViewport?.addEventListener('resize',fitSimulatorViewport);window.addEventListener('resize',fitSimulatorViewport);fitSimulatorViewport();
